<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{request}from'../../api/client';const items=ref<any[]>([]);async function load(){try{items.value=(await request('/api/v1/admin/dramas?page=1&page_size=100')).items||[]}catch{items.value=[{id:101,title:'The Contract Wife',country:'US',language:'en',status:1,is_paid:true},{id:102,title:'Revenge of the Hidden Heiress',country:'US',language:'en',status:1,is_paid:true}];ElMessage.warning('API 未启动，当前显示演示数据')}}async function toggle(x:any){try{await request('/api/v1/admin/dramas/'+x.id+'/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:x.status===1?2:1})});await load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load)</script>
<template><section><div class="title"><p>CONTENT</p><h1>短剧管理</h1><span>发布、下架与内容维护</span></div><el-card><template #header><div class="head">短剧列表 <el-button type="primary" @click="$router.push('/dramas/create')">+ 发布短剧</el-button></div></template><el-table :data="items" stripe><el-table-column prop="id" label="ID"/><el-table-column prop="title" label="标题" min-width="220"/><el-table-column prop="country" label="国家"/><el-table-column prop="language" label="语言"/><el-table-column label="类型"><template #default="{row}">{{row.is_paid?'付费':'免费'}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'已发布':'草稿'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="toggle(row)">{{row.status===1?'下架':'发布'}}</el-button></template></el-table-column></el-table></el-card></section></template>